package com.bocsoft.sqleditor.history;
import com.bocsoft.sqleditor.auth.AuthContext;import com.bocsoft.sqleditor.common.ApiException;import com.bocsoft.sqleditor.datasource.DataSourceService;import com.bocsoft.sqleditor.datasource.api.CursorPage;import com.bocsoft.sqleditor.history.api.*;import com.bocsoft.sqleditor.history.persistence.*;import com.bocsoft.sqleditor.metadata.MetadataCursorCodec;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;
@Service public class HistoryQueryService {private final ExecutionHistoryMapper mapper;private final MetadataCursorCodec cursors;private final DataSourceService dataSources;public HistoryQueryService(ExecutionHistoryMapper mapper,MetadataCursorCodec cursors,DataSourceService dataSources){this.mapper=mapper;this.cursors=cursors;this.dataSources=dataSources;}
 public CursorPage<HistorySummary>list(AuthContext auth,String keyword,String source,String database,String status,String type,int size,String token){String q=clean(keyword,200,"keyword");if(size<1||size>100)throw ApiException.validation("pageSize","OUT_OF_RANGE","每页数量必须在 1 到 100 之间");validateEnum("status",status,new HashSet<String>(Arrays.asList("RUNNING","SUCCESS","FAILED","CANCELLED","TIMEOUT")));validateEnum("statementType",type,new HashSet<String>(Arrays.asList("SELECT","INSERT","UPDATE","DELETE","REPLACE","DDL","OTHER")));String scope="history|"+q+"|"+nulls(source)+"|"+nulls(database)+"|"+nulls(status)+"|"+nulls(type)+"|"+size;String after=cursors.decode(token,scope);Instant cursorTime=null;String cursorId=null;if(after!=null){int p=after.lastIndexOf('|');try{cursorTime=Instant.parse(after.substring(0,p));cursorId=after.substring(p+1);}catch(Exception e){throw ApiException.validation("pageToken","INVALID","分页游标无效");}}String pattern=q.isEmpty()?null:"%"+escape(q)+"%";List<ExecutionHistoryRecord>records=mapper.listOwned(auth.getUserId(),pattern,blank(source),blank(database),blank(status),blank(type),cursorTime,cursorId,size+1);boolean more=records.size()>size;List<HistorySummary>items=new ArrayList<HistorySummary>();for(int i=0;i<Math.min(size,records.size());i++)items.add(new HistorySummary(records.get(i)));String next=null;if(more&&!items.isEmpty()){ExecutionHistoryRecord last=records.get(size-1);next=cursors.encode(last.getStartedAt().toString()+"|"+last.getId(),scope);}return new CursorPage<HistorySummary>(items,next);}
 public HistoryDetail detail(AuthContext auth,String id){ExecutionHistoryRecord r=mapper.findOwned(id,auth.getUserId());if(r==null)throw new ApiException(HttpStatus.NOT_FOUND,"EXECUTION_NOT_FOUND","执行不存在");boolean available=true;try{dataSources.get(auth,r.getDataSourceId());}catch(ApiException e){available=false;}return new HistoryDetail(r,available);}private String clean(String v,int n,String f){String x=v==null?"":v.trim();if(x.length()>n)throw ApiException.validation(f,"OUT_OF_RANGE","筛选值过长");return x;}private String blank(String v){return v==null||v.trim().isEmpty()?null:v.trim();}private String nulls(String v){return v==null?"":v.trim();}private String escape(String v){return v.replace("\\","\\\\").replace("%","\\%").replace("_","\\_");}private void validateEnum(String f,String v,Set<String>allowed){if(v!=null&&!v.trim().isEmpty()&&!allowed.contains(v.trim().toUpperCase(Locale.ROOT)))throw ApiException.validation(f,"INVALID","筛选值不合法");}}
